template <typename TQueryType>
MTPinitConnection<TQueryType>::MTPinitConnection() = default;
template <typename TQueryType>
MTPinitConnection<TQueryType>::MTPinitConnection(const MTPflags<MTPinitConnection::Flags> &flags_, MTPint api_id_, const MTPstring &device_model_, const MTPstring &system_version_, const MTPstring &app_version_, const MTPstring &system_lang_code_, const MTPstring &lang_pack_, const MTPstring &lang_code_, const MTPInputClientProxy &proxy_, const MTPJSONValue &params_, const TQueryType &query_) : _flags(flags_), _api_id(api_id_), _device_model(device_model_), _system_version(system_version_), _app_version(app_version_), _system_lang_code(system_lang_code_), _lang_pack(lang_pack_), _lang_code(lang_code_), _proxy(proxy_), _params(params_), _query(query_) {
}
template <typename TQueryType>
template <typename Prime>
bool MTPinitConnection<TQueryType>::read(const Prime *&from, const Prime *end, mtpTypeId cons) {
	return _flags.read(from, end)
		&& _api_id.read(from, end)
		&& _device_model.read(from, end)
		&& _system_version.read(from, end)
		&& _app_version.read(from, end)
		&& _system_lang_code.read(from, end)
		&& _lang_pack.read(from, end)
		&& _lang_code.read(from, end)
		&& ((_flags.v & Flag::f_proxy) ? _proxy.read(from, end) : ((_proxy = MTPInputClientProxy()), true))
		&& ((_flags.v & Flag::f_params) ? _params.read(from, end) : ((_params = MTPJSONValue()), true))
		&& _query.read(from, end);
}
template <typename TQueryType>
template <typename Accumulator>
void MTPinitConnection<TQueryType>::write(Accumulator &to) const {
	_flags.write(to);
	_api_id.write(to);
	_device_model.write(to);
	_system_version.write(to);
	_app_version.write(to);
	_system_lang_code.write(to);
	_lang_pack.write(to);
	_lang_code.write(to);
	if (_flags.v & Flag::f_proxy) _proxy.write(to);
	if (_flags.v & Flag::f_params) _params.write(to);
	_query.write(to);
}
